
(function(){function feedback(b,ok){var prev=b.innerHTML;b.textContent=ok?(b.dataset.success||'已复制'):'请手动复制';setTimeout(function(){b.innerHTML=prev},2100)}function fallback(b,v){var el=document.createElement('textarea');el.value=v;el.style.position='fixed';el.style.left='-9999px';document.body.appendChild(el);el.select();var ok=false;try{ok=document.execCommand('copy')}catch(e){}el.remove();if(ok)feedback(b,true);else{window.prompt(b.dataset.prompt||'请复制以下内容：',v);feedback(b,false)}}document.querySelectorAll('[data-copy]').forEach(function(b){b.addEventListener('click',function(){var v=b.getAttribute('data-copy');if(navigator.clipboard&&window.isSecureContext){navigator.clipboard.writeText(v).then(function(){feedback(b,true)}).catch(function(){fallback(b,v)})}else fallback(b,v)})})})();
